import { createCsrfMiddleware, createMiddleware, createStart } from "@tanstack/react-start";
import { withSecurityHeaders } from "@/lib/security-headers";

/**
 * TanStack Start instance (server entry options).
 *
 * Why this file exists: Cloudflare does not apply `public/_headers` to
 * responses generated by Worker code, and the live `meridian` worker
 * server-renders every HTML page. This request middleware adds the shared
 * security headers (src/lib/security-headers.ts) to every response that
 * passes through the TanStack handler. This covers SSR HTML,
 * `/api/contact`, and redirects, on any host adapter (Cloudflare, Vercel,
 * preview). Static assets keep getting the same headers from
 * `public/_headers`.
 *
 * Defining `startInstance` replaces TanStack's built-in default request
 * middleware, which is CSRF protection for server functions. The CSRF
 * middleware is re-added first, with the same server-function filter, so
 * that protection is unchanged.
 */
const csrfMiddleware = createCsrfMiddleware({
  filter: (ctx) => ctx.handlerType === "serverFn",
});

const securityHeadersMiddleware = createMiddleware().server(async ({ next }) => {
  const result = await next();
  return { ...result, response: withSecurityHeaders(result.response) };
});

export const startInstance = createStart(() => ({
  requestMiddleware: [csrfMiddleware, securityHeadersMiddleware],
}));
